-- Schema chamcong (đã áp dụng lên Supabase project jnzeawdffiwnblrlwtgx ngày 2026-11-09)
create schema if not exists chamcong;
create table chamcong.ca_live (id text primary key, ngay date, ten text not null, vi_tri text, kenh text, bat_dau text, ket_thuc text, gio_live numeric default 0, gmv numeric default 0, ghi_chu text, tao_luc text, gmv_dau numeric default 0, gmv_cuoi numeric default 0, anh_dau text, anh_cuoi text);
create index on chamcong.ca_live (ngay); create index on chamcong.ca_live (kenh); create index on chamcong.ca_live (lower(ten));
create table chamcong.nhan_su (ten text primary key, tao_luc text, ma_nv text);
create table chamcong.kenh (ten text primary key, tao_luc text);
create table chamcong.luong_cu (id bigserial primary key, ten text, vi_tri text, don_gia_gio numeric, pct_gmv numeric);
create table chamcong.yeu_cau (id text primary key, ma_ca text, nguoi_gui text, username text, kenh text, ngay_ca text, gui_luc text, kt_cu text, kt_moi text, gmv_dau_cu numeric, gmv_dau_moi numeric, gmv_cuoi_cu numeric, gmv_cuoi_moi numeric, ghi_chu_cu text, ghi_chu_moi text, trang_thai text, nguoi_duyet text, duyet_luc text, ly_do_tu_choi text, vi_tri_cu text, vi_tri_moi text, kenh_cu text, kenh_moi text, bd_cu text, bd_moi text);
create index on chamcong.yeu_cau (trang_thai);
create table chamcong.luong_gio (ten text not null, kenh text not null default '', don_gia_host numeric default 0, don_gia_tro numeric default 0, primary key (ten, kenh));
create table chamcong.thuong_moc (ten text not null, kenh text not null default '', vai_tro text not null default '', moc_gmvh numeric default 0, moc_nmv numeric default 0, primary key (ten, kenh, vai_tro));
create table chamcong.thuong_chung (khoa text primary key, gia_tri text);
create table chamcong.hoan_huy (thang text primary key, ty_le numeric);
create table chamcong.diem_thang (thang text not null, ten text not null, diem numeric, primary key (thang, ten));
create table chamcong.thuong_ho_tro (id text primary key, thang text, ten text, kenh text, so_tien numeric default 0, ghi_chu text);
create index on chamcong.thuong_ho_tro (thang);
create table chamcong.thang_chot (thang text primary key, trang_thai text, nguoi_chot text, chot_luc text, ghi_chu text, ty_le_hoan_huy numeric);
create table chamcong.luong_chot (thang text not null, ten text not null, tong_luong_gio numeric, tong_thuong numeric, thuong_ho_tro numeric, ghi_chu_ho_tro text, diem numeric, tong_thu_nhap numeric, lines_json text, chot_boi text, chot_luc text, luong_cung numeric, ho_tro_items_json text, luong_cung_items_json text, thu_viec numeric, thu_viec_items_json text, primary key (thang, ten));
create table chamcong.nhan_su_luong_cung (ten text primary key, vai_tro text, ghi_chu text, trang_thai text, tao_luc text);
create table chamcong.luong_cung_thang (thang text not null, ten text not null, kenh text not null default '', so_tien numeric default 0, ghi_chu text, primary key (thang, ten, kenh));
create table chamcong.luong_thu_viec (thang text not null, ten text not null, kenh text not null default '', so_tien numeric default 0, ghi_chu text, primary key (thang, ten, kenh));
create table chamcong.ngay_le (ngay text primary key, he_so numeric, ghi_chu text);
create table chamcong.users (username text primary key, hash text, salt text, vai_tro text, kenh text, nhan_su text, tao_luc text, da_thiet_lap text, kenh_quan_ly text);
create table chamcong.tiktok_auth (kenh text primary key, open_id text, access_token text, access_exp text, refresh_token text, refresh_exp text, ket_noi_luc text, user_type text, granted_scopes text);
create table chamcong.app_config (key text primary key, value text);
do $$ declare t text; begin for t in select tablename from pg_tables where schemaname='chamcong' loop execute format('alter table chamcong.%I enable row level security', t); end loop; end $$;
revoke all on schema chamcong from anon, authenticated;
revoke all on all tables in schema chamcong from anon, authenticated;
grant usage on schema chamcong to service_role;
grant all on all tables in schema chamcong to service_role;
grant all on all sequences in schema chamcong to service_role;
insert into storage.buckets (id, name, public) values ('chamcong-photos','chamcong-photos', false) on conflict (id) do nothing;
